const baseStartSim=startSim;startSim=function(){const w=sop(),plan=canEdit()?w.stagePlan:w.published?.definition?.stagePlan;if(plan?.stages.length){ownerId=compositionEnsureWorkflowId(w);compositionStartPractice();return;}return baseStartSim();};
window.compositionEditStage=function(id,key,value){if(!canEdit()||owner().nestedPractice)return;const s=owner().stagePlan?.stages.find(s=>s.id===id);if(!s)return;s[key]=value;save();if(['childWorkflowId','approvalRequired','waitDaysRef','repeatCheckHoursRef'].includes(key))compositionRenderPlan();};
window.compositionAddStage=function(){if(!canEdit()||owner().nestedPractice)return;const p=owner().stagePlan??={stages:[]};p.stages.push({id:'stage-'+crypto.randomUUID(),label:'New stage',childWorkflowId:'',dependencies:[],approvalRequired:false,approvalRole:'Director',waitDays:0,repeatCheckHours:0});save();compositionRenderPlan();};
